import{_ as l,o as r,c as n,j as e,a}from"./chunks/framework.CAXxHpAX.js";const f=JSON.parse('{"title":"论坛语录-宇宙统一场","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/论坛语录-宇宙统一场.md","filePath":"60-原文段落/论坛语录-宇宙统一场.md","lastUpdated":1778155802000}'),o={name:"60-原文段落/论坛语录-宇宙统一场.md"};function s(_,t,c,d,p,i){return r(),n("div",null,[...t[0]||(t[0]=[e("h1",{id:"论坛语录-宇宙统一场",tabindex:"-1"},[a("论坛语录-宇宙统一场 "),e("a",{class:"header-anchor",href:"#论坛语录-宇宙统一场","aria-label":'Permalink to "论坛语录-宇宙统一场"'},"​")],-1),e("blockquote",null,[e("p",null,[a("来源："),e("a",{href:"/01-Raw-Sources/论坛下_06_了空居士论坛语录（一）"},"论坛下_06_了空居士论坛语录（一）"),a(" 切分日期：2026-05-06")])],-1),e("hr",null,null,-1),e("p",null,'从场的统一性和万物基本构成物的统一性可以看出，自然万物之间既有它的独立性，也有它的统一性，那些统一的部分便形成了宇宙的大场，这个大场就是现代人所说的"宇宙统一场"，古人所说的"天"、"道"、"实相"。',-1),e("p",null,'"天人合一"、"炼虚合道"、"明心见性"在大方向上是一致的，在层次上还有粗细之分。修炼达到"虚空"层次，便可认为是"天人合一"；修炼初步达到"虚空粉碎"，便可算是"炼虚合道"。惟有"明心见性"、亲证"实相"，这个层次最为精微，这个层次的场是零维，是彻底的虚空粉碎。',-1),e("p",null,'"场"的层次是很多很多的，用"一花一世界，一叶一菩提"来形容还远远不够。从理论上来讲，一朵花既有它整朵花的整体场，它的各个组成部分也有各自不同的场……依此来看，小小的一朵花它的场就无穷无尽了，更何况浩瀚宇宙，物象无量！性质相同的场就会彼此融通成为一体，性质相近的场就会部分沟通，互相影响。但是一定没有绝对相反的场，也就是不管如何对立，总是还有一部分是统一的，那就是上述所说的"宇宙统一场"，也就是众生的"佛性"，万物的"法性"。',-1)])])}const m=l(o,[["render",s]]);export{f as __pageData,m as default};
